import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_ptf(n, m):
        clauses = []
        for _ in range(m):
            literals = [random.choice([1, -1]) * (i + 1) for i in range(n)]
            clauses.append(literals)
        return clauses

    def matrix_multiplication(A, B):
        rows_A, cols_A = len(A), len(A[0])
        cols_B = len(B[0])
        result = [[0] * cols_B for _ in range(rows_A)]
        for i in range(rows_A):
            for j in range(cols_B):
                for k in range(cols_A):
                    result[i][j] += A[i][k] * B[k][j]
        return result

    def gaussian_elimination(A, b):
        n = len(A)
        for i in range(n):
            max_row = i
            for j in range(i + 1, n):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            b[i], b[max_row] = b[max_row], b[i]
            for j in range(i + 1, n):
                factor = A[j][i] / A[i][i]
                for k in range(i, n):
                    A[j][k] -= factor * A[i][k]
                b[j] -= factor * b[i]
        x = [0] * n
        for i in range(n - 1, -1, -1):
            x[i] = (b[i] - sum(A[i][j] * x[j] for j in range(i + 1, n))) / A[i][i]
        return x

    def minimal_rank(clauses):
        n = len(clauses[0])
        m = len(clauses)
        A = [[0] * (n + m) for _ in range(n)]
        b = [0] * n
        for i, clause in enumerate(clauses):
            for j, literal in enumerate(clause):
                A[j][i] = literal
            b[i] = 1

        try:
            x = gaussian_elimination(A, b)
            return sum(abs(val) for val in x)
        except ZeroDivisionError:
            return float('inf')

    n_values = [5, 10, 15, 20, 30, 40]
    results = []
    for n in n_values:
        for _ in range(5):  # Ensure at least 5 instances per seed
            m = random.randint(n, 2 * n)
            ptf = generate_ptf(n, m)
            rank = minimal_rank(ptf)
            predicted_value = (m ** 0.25) * (n ** 0.75)
            results.append((rank, predicted_value))

    mean_metric_value = sum(rank / predicted for rank, predicted in results) / len(results)
    std_metric_value = math.sqrt(sum((rank / predicted - mean_metric_value) ** 2 for rank, predicted in results) / len(results))
    conjecture_holds = all(0.5 <= rank / predicted <= 2.5 for rank, predicted in results)

    return {
        "metric_name": "Minimal Rank Ratio",
        "metric_value": mean_metric_value,
        "instances_tested": len(results),
        "conjecture_holds": conjecture_holds,
        "counterexample": "" if conjecture_holds else "mapping_undefined"
    }

